  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "Initialize ST20 pressure thresholds and test limits."
    },
    {
      "rung": 2,
      "purpose": "Detect PT-2001 wire break fault condition."
    },
    {
      "rung": 3,
      "purpose": "Detect ST20 pack overpressure alarm condition."
    },
    {
      "rung": 4,
      "purpose": "Detect ST20 supply air low alarm while station is busy."
    },
    {
      "rung": 5,
      "purpose": "Reset ST20 alarm flags via fault reset pushbutton."
    },
    {
      "rung": 6,
      "purpose": "Aggregate ST20 faults (including E-stop loss) and drive fault beacon."
    },
    {
      "rung": 7,
      "purpose": "Manual vent valve control when not in auto mode."
    },
    {
      "rung": 8,
      "purpose": "Start ST20 auto cycle, set busy flag, and clear previous results."
    },
    {
      "rung": 9,
      "purpose": "Transition from CLAMP to FILL step when clamp is fully closed."
    },
    {
      "rung": 10,
      "purpose": "Run ST20 fill step timeout timer."
    },
    {
      "rung": 11,
      "purpose": "Trigger fill timeout alarm if fill step timer completes."
    },
    {
      "rung": 12,
      "purpose": "Transition from FILL to STABILIZE step when fill pressure is reached."
    },
    {
      "rung": 13,
      "purpose": "Run ST20 stabilize step timer."
    },
    {
      "rung": 14,
      "purpose": "Capture test start pressure upon test window timer completion."
    },
    {
      "rung": 15,
      "purpose": "Transition from STABILIZE to TEST step when timer completes."
    },
    {
      "rung": 16,
      "purpose": "Run ST20 pressure decay test window timer."
    },
    {
      "rung": 17,
      "purpose": "Capture test end pressure and calculate pressure drop."
    },
    {
      "rung": 18,
      "purpose": "Evaluate PASS/FAIL result by comparing pressure drop to max allowed limit."
    },
    {
      "rung": 19,
      "purpose": "Transition from TEST to VENT step when test window timer completes."
    },
    {
      "rung": 20,
      "purpose": "Abort cycle to VENT step and force FAIL result upon general fault."
    },
    {
      "rung": 21,
      "purpose": "Run ST20 vent step timer."
    },
    {
      "rung": 22,
      "purpose": "Transition from VENT to UNCLAMP step when vented and safe."
    },
    {
      "rung": 23,
      "purpose": "Transition from UNCLAMP to COMPLETE step when clamp is open."
    },
    {
      "rung": 24,
      "purpose": "Clear busy flag and COMPLETE step when pallet leaves test position."
    },
    {
      "rung": 25,
      "purpose": "Energize clamp close solenoid during active cycle steps."
    },
    {
      "rung": 26,
      "purpose": "Energize fill valve during FILL step if no fault is active."
    },
    {
      "rung": 27,
      "purpose": "Energize vent valve during VENT step or upon overpressure."
    },
    {
      "rung": 28,
      "purpose": "Output PASS/FAIL signals to line controller during COMPLETE step."
    },
    {
      "rung": 29,
      "purpose": "End of ST20 program."
    }
  ],
  "suspicious": [
